"""Independent O08 qualification specification. No planner imports or I/O.
Trusted profile and validity view are admitted independently of candidate proof.
"""
import json,hashlib

def canonical(x):
    def check(v):
        if type(v) not in (dict,list,str,int,bool,type(None)):raise ValueError('type')
        if type(v) is dict:
            if any(type(k) is not str for k in v):raise ValueError('key')
            for y in v.values():check(y)
        if type(v) is list:
            for y in v:check(y)
    check(x)
    return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(x):return hashlib.sha256(canonical(x)).hexdigest()
def raw(x):return hashlib.sha256(x.encode('utf-8')).hexdigest()
def exact(a,b):return canonical(a)==canonical(b)
def fields(x,s):return type(x) is dict and set(x)==set(s.split())
def reject(c):return {'accepted':False,'failed_clause':c,'gate_supported':False}
def admit(p,s,v):
    try:return evaluate(p,s,v)
    except (KeyError,TypeError,ValueError,UnicodeError):return reject('C00_SCHEMA')
def evaluate(p,s,v):
    if not fields(s,'schema mode profile_pin proof documents') or s['schema']!='O08-INPUT-1' or s['mode']!='SYNTHETIC_QUALIFICATION_ONLY' or s['profile_pin']!=digest(p):return reject('C00_SCHEMA')
    q=s['proof']
    if q is None:return reject('C01_PROOF')
    if not fields(q,'schema identity predicate gate proof_type context preparation dossier decision authority source_lineage scope supports provenance implementation_preconditions downstream'):return reject('C00_SCHEMA')
    if q['schema']!='O08-GATE-PROOF-1' or q['gate']!=p['gate'] or q['predicate']!=p['predicate']:return reject('C02_GATE')
    if q['proof_type']!=p['proof_type']:return reject('C03_PROOF_TYPE')
    if q['preparation']!={'type':p['preparation_type'],'admission':'ACCEPTED_FOR_PINNED_SNAPSHOT','source':p['supports']['preparation']}:return reject('C04_PREPARATION')
    if q['dossier']!=p['supports']['dossier']:return reject('C05_DOSSIER')
    if q['decision']!={'type':p['decision_type'],'id':'DEC-VALIDATOR','option':'APPROVED_OPTION_1','record_identity':p['authority_identity']}:return reject('C06_DECISION')
    a=q['authority']
    if a is None:return reject('C07_AUTHORITY_REQUIRED')
    if not fields(a,'identity record') or a['identity']!=p['authority_identity']:return reject('C08_AUTHORITY_IDENTITY')
    r=a['record']; original=p['authority_record']
    if type(r) is not dict or r.get('schema')!='E1-ARCHITECT-DECISION-AUTHORITY-1' or r.get('record_type')!='DEC-VALIDATOR' or r.get('status')!='ISSUED':return reject('C09_AUTHORITY_TYPE_STATUS')
    if r.get('decision')!='APPROVED_OPTION_1':return reject('C06_DECISION')
    if r.get('source_artifacts')!=p['source_lineage'] or q['source_lineage']!=p['source_lineage']:return reject('C10_SOURCE_LINEAGE')
    if r.get('scope')!=p['scope'] or q['scope']!=p['scope']:return reject('C11_SCOPE')
    if r.get('preconditions')!=['CONTRACT-T1'] or q['implementation_preconditions']!=['CONTRACT-T1']:return reject('C12_PRECONDITIONS')
    for k in ['authorized_operation','api','sharing_requirement','authority_not_granted','runtime_effects_authorized','candidate3_authority_consumed','validator_pass_grants_authority','validation_prohibited_effects','implementation_performed']:
        if k not in r or not exact(r[k],original[k]):return reject('C13_PERMISSION_BOUNDARY')
    if q['context']!=p['context']:return reject('C14_CONTEXT')
    if q['supports']!=p['supports'] or q['provenance']!={'method':'O08_ACCEPTED_CHAIN_1','sources':p['supports']}:return reject('C15_BINDINGS')
    if not exact(q['downstream'],{'gate':'gate:validator_authority','conditional_action':'IMPL-VALIDATOR','remaining_preconditions':['CONTRACT-T1'],'slots_resolved':[],'validator_complete':False}):return reject('C16_GATE_BOUNDARY')
    if not fields(v,'context sources') or v['context']!=p['context'] or set(v['sources'])!=set(p['supports']):return reject('C17_VALIDITY')
    for role,pin in p['supports'].items():
        if v['sources'][role]!={'identity':pin['identity'],'state':'CURRENT_AT_PINNED_SNAPSHOT'}:return reject('C17_VALIDITY')
    if type(s['documents']) is not dict or set(s['documents'])!=set(p['supports']):return reject('C18_SOURCE_BYTES')
    for role,pin in p['supports'].items():
        if type(s['documents'][role]) is not str or raw(s['documents'][role])!=pin['identity']['sha256']:return reject('C18_SOURCE_BYTES')
    if not exact(r,original) or not exact(json.loads(s['documents']['authority']),r):return reject('C19_RECORD_CORRESPONDENCE')
    if r['authority_id']!='E1-ArchitectDecisionAuthority-sha256:'+digest({k:x for k,x in r.items() if k!='authority_id'}):return reject('C20_AUTHORITY_HASH')
    if any(t not in s['documents']['preparation'] for t in p['required_preparation_excerpts']) or any(t not in s['documents']['dossier'] for t in p['required_dossier_excerpts']) or p['required_propagation_excerpt'] not in s['documents']['propagation']:return reject('C21_ACCEPTED_CHAIN')
    wanted={'domain':'CONTENT_IDENTITY','namespace':'O08GateProof-sha256','sha256':digest({k:x for k,x in q.items() if k!='identity'})}
    if q['identity']!=wanted:return reject('C22_PROOF_IDENTITY')
    return {'accepted':True,'failed_clause':None,'gate_supported':True,'gate':'gate:validator_authority','slot_transition':'UNCHANGED','validator_complete':False,'implementation_action_eligible':False,'authority_issued_by_evaluation':False,'evaluation':'PINNED_SNAPSHOT_ONLY'}
